#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct DSU {
    vector<int> parent;
    vector<int> L;
    vector<int> R;
    DSU(int n) : parent(n + 1), L(n + 1), R(n + 1) {
        for (int i = 1; i <= n; i++) {
            parent[i] = i;
            L[i] = i;
            R[i] = i;
        }
    }
    int find(int i) {
        if (parent[i] == i)
            return i;
        return parent[i] = find(parent[i]);
    }
    void unite(int i, int j) {
        int root_i = find(i);
        int root_j = find(j);
        if (root_i != root_j) {
            parent[root_i] = root_j;
            L[root_j] = min(L[root_j], L[root_i]);
            R[root_j] = max(R[root_j], R[root_i]);
        }
    }
};

int N, Q;
long long K;
vector<long long> A;
vector<long long> X, Y;
vector<long long> valsX, valsY;
vector<vector<int>> posX, posY;

int query_count(const vector<long long>& vals, const vector<vector<int>>& pos, long long target_val, int low, int high) {
    if (low > high) return 0;
    auto it = lower_bound(vals.begin(), vals.end(), target_val);
    if (it == vals.end() || *it != target_val) return 0;
    int idx = it - vals.begin();
    const auto& vec = pos[idx];
    auto it1 = lower_bound(vec.begin(), vec.end(), low);
    auto it2 = upper_bound(vec.begin(), vec.end(), high);
    return (int)(it2 - it1);
}

long long count_pairs_with_i(int i, int L_j, int R_j) {
    long long ans = 0;
    // Condição 1: X_j = X_i + K, j <= i + K
    long long max_j_1 = (long long)i + K;
    int high_1 = (max_j_1 < R_j) ? (int)max_j_1 : R_j;
    if (L_j <= high_1) {
        ans += query_count(valsX, posX, X[i] + K, L_j, high_1);
    }
    // Condição 2: Y_j = Y_i - K, j <= i + K - 1
    long long max_j_2 = (long long)i + K - 1;
    int high_2 = (max_j_2 < R_j) ? (int)max_j_2 : R_j;
    if (L_j <= high_2) {
        ans += query_count(valsY, posY, Y[i] - K, L_j, high_2);
    }
    return ans;
}

long long count_pairs_with_j(int j, int L_i, int R_i) {
    long long ans = 0;
    // Condição 1: X_i = X_j - K, i >= j - K
    long long min_i_1 = (long long)j - K;
    int low_1 = (min_i_1 > L_i) ? (int)min_i_1 : L_i;
    if (low_1 <= R_i) {
        ans += query_count(valsX, posX, X[j] - K, low_1, R_i);
    }
    // Condição 2: Y_i = Y_j + K, i >= j - K + 1
    long long min_i_2 = (long long)j - K + 1;
    int low_2 = (min_i_2 > L_i) ? (int)min_i_2 : L_i;
    if (low_2 <= R_i) {
        ans += query_count(valsY, posY, Y[j] + K, low_2, R_i);
    }
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> N >> Q >> K)) return 0;

    A.resize(N + 1);
    X.resize(N + 1);
    Y.resize(N + 1);

    for (int i = 1; i <= N; i++) {
        cin >> A[i];
        X[i] = A[i] + i;
        Y[i] = A[i] - i;
        valsX.push_back(X[i]);
        valsY.push_back(Y[i]);
    }

    sort(valsX.begin(), valsX.end());
    valsX.erase(unique(valsX.begin(), valsX.end()), valsX.end());

    sort(valsY.begin(), valsY.end());
    valsY.erase(unique(valsY.begin(), valsY.end()), valsY.end());

    posX.resize(valsX.size());
    posY.resize(valsY.size());

    for (int i = 1; i <= N; i++) {
        int idxX = lower_bound(valsX.begin(), valsX.end(), X[i]) - valsX.begin();
        posX[idxX].push_back(i);
        int idxY = lower_bound(valsY.begin(), valsY.end(), Y[i]) - valsY.begin();
        posY[idxY].push_back(i);
    }

    vector<int> D(Q + 1);
    vector<bool> will_collapse(N + 1, false);
    for (int t = 1; t <= Q; t++) {
        cin >> D[t];
        will_collapse[D[t]] = true;
    }

    DSU dsu(N);
    vector<bool> active(N + 1, false);
    long long current_answer = 0;

    auto activate_step = [&](int u) {
        int L = u, R = u;
        int comp_L_root = -1, comp_R_root = -1;

        if (u > 1 && active[u - 1]) {
            comp_L_root = dsu.find(u - 1);
            L = dsu.L[comp_L_root];
        }
        if (u < N && active[u + 1]) {
            comp_R_root = dsu.find(u + 1);
            R = dsu.R[comp_R_root];
        }

        long long new_pairs = 0;

        if (comp_L_root != -1) {
            new_pairs += count_pairs_with_j(u, L, u - 1);
        }
        if (comp_R_root != -1) {
            new_pairs += count_pairs_with_i(u, u + 1, R);
        }
        if (comp_L_root != -1 && comp_R_root != -1) {
            int sz_L = u - L;
            int sz_R = R - u;
            if (sz_L <= sz_R) {
                for (int i = L; i <= u - 1; i++) {
                    new_pairs += count_pairs_with_i(i, u + 1, R);
                }
            } else {
                for (int j = u + 1; j <= R; j++) {
                    new_pairs += count_pairs_with_j(j, L, u - 1);
                }
            }
        }

        active[u] = true;
        if (comp_L_root != -1) dsu.unite(u - 1, u);
        if (comp_R_root != -1) dsu.unite(u + 1, u);

        current_answer += new_pairs;
    };

    // Ativa inicialmente todos os degraus que nunca desmoronaram
    for (int i = 1; i <= N; i++) {
        if (!will_collapse[i]) {
            activate_step(i);
        }
    }

    vector<long long> ans(Q + 1);
    ans[Q] = current_answer;

    // Processamento reverso para os degraus que desmoronaram
    for (int t = Q; t >= 1; t--) {
        activate_step(D[t]);
        ans[t - 1] = current_answer;
    }

    for (int t = 0; t <= Q; t++) {
        cout << ans[t] << "\n";
    }

    return 0;
}
